package io.github.yuroyami.imagekodec

import io.github.yuroyami.imagekodec.codec.JpxDecoder
import kotlin.test.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertTrue

/**
 * Native FFmpeg jpeg2000: -pred 0/1, -tile_width 16, -tile_height 16, -format j2k.
 * The ordinary control uses OpenJPEG -I -n 5 -t 16,16 -r 1; all expected pixels
 * are OpenJPEG's decoded samples of the same deterministic gray gradients.
 */
class Jp2SingletonTest {
    internal fun encoded(name: String): ByteArray = hex(streams.getValue(name))
    private fun compare(name: String, tolerance: Int) {
        val result = assertNotNull(JpxDecoder.decode(encoded(name)), name)
        val reference = hex(references.getValue(name))
        val size = sizes.getValue(name)
        assertEquals(size.first, result.width)
        assertEquals(size.second, result.height)
        assertEquals("DeviceGray", result.colorSpace)
        assertEquals(reference.size, result.pixelBytes.size)
        if (tolerance == 0) assertContentEquals(reference, result.pixelBytes, name)
        else for (i in reference.indices) {
            val delta = kotlin.math.abs((reference[i].toInt() and 255) - (result.pixelBytes[i].toInt() and 255))
            assertTrue(delta <= tolerance, "$name sample $i differs by $delta")
        }
    }
    @Test fun irreversibleHorizontalSingletonsMatchOpenjpeg() { compare("horizontal", 4) }
    @Test fun irreversibleVerticalSingletonsMatchOpenjpeg() { compare("vertical", 4) }
    @Test fun irreversibleCornerSingletonsMatchOpenjpeg() { compare("corner", 4) }
    @Test fun reversibleSingletonsStayExact() { compare("reversible", 0) }
    @Test fun ordinaryOpenjpegTilesKeepTheirPixels() { compare("ordinary", 4) }

    private val sizes = mapOf(
        "horizontal" to (32 to 16),
        "vertical" to (16 to 32),
        "corner" to (32 to 32),
        "reversible" to (32 to 16),
        "ordinary" to (32 to 16),
    )
    private val streams = mapOf(
        "horizontal" to "",
        "vertical" to "",
        "corner" to "",
        "reversible" to "",
        "ordinary" to "",
    )
    private val references = mapOf(
        "horizontal" to "",
        "vertical" to "",
        "corner" to "",
        "reversible" to "",
        "ordinary" to "",
    )
}
